"""Legacy CRM storage convention conversion utilities."""

from __future__ import annotations

from datetime import date
from decimal import Decimal, ROUND_HALF_UP


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO YYYY-MM-DD."""
    if yyyymmdd is None or yyyymmdd == "" or yyyymmdd == "00000000":
        return None

    if len(yyyymmdd) != 8 or not yyyymmdd.isdigit():
        raise ValueError(f"Invalid legacy date: {yyyymmdd!r}")

    try:
        return date(
            int(yyyymmdd[0:4]),
            int(yyyymmdd[4:6]),
            int(yyyymmdd[6:8]),
        ).isoformat()
    except ValueError as exc:
        raise ValueError(f"Invalid legacy date: {yyyymmdd!r}") from exc


def from_iso(iso: str | None) -> str:
    """Convert an ISO YYYY-MM-DD date to the legacy YYYYMMDD representation."""
    if iso is None or iso == "":
        return "00000000"

    if len(iso) != 10 or iso[4] != "-" or iso[7] != "-":
        raise ValueError(f"Invalid ISO date: {iso!r}")

    try:
        parsed = date.fromisoformat(iso)
    except ValueError as exc:
        raise ValueError(f"Invalid ISO date: {iso!r}") from exc

    return parsed.strftime("%Y%m%d")


def yn(char: str | None) -> bool:
    """Convert legacy Y/N/blank boolean storage to a Python boolean."""
    return char == "Y"


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a legacy amount to minor currency units using half-up rounding."""
    if amount is None or amount == "":
        return 0

    effective_currency = "USD" if currency is None or currency == "" else currency
    exponent = 0 if effective_currency == "JPY" else 2
    scale = Decimal(10) ** exponent

    value = Decimal(str(amount))
    return int((value * scale).to_integral_value(rounding=ROUND_HALF_UP))
